#!/usr/bin/env python3
"""
Shared utilities for the tokenizer pipeline.
"""

import os
import re
from collections import Counter
from pathlib import Path
from typing import Any, Dict, List, Set

import sentencepiece as spm

# Matches auto-generated byte-fallback tokens like <0x00>, <0xFF>.
# These are created automatically by SentencePiece when byte_fallback=True,
# so they must NOT appear in user_defined_symbols (which would cause a
# "duplicated symbols" error on the next training stage).
_BYTE_TOKEN_RE = re.compile(r"^<0x[0-9a-fA-F]{2}>$")


# ---------------------------------------------------------------------------
# Token extraction
# ---------------------------------------------------------------------------

def extract_tokens_from_model(model_path: str) -> List[str]:
    """
    Extract all non-special token strings from a SentencePiece model.

    Skips the four reserved IDs (unk, bos, eos, pad) and control tokens,
    but keeps byte-fallback tokens (<0x41> etc.) since those contribute to
    coverage and should remain stable across pipeline stages.
    """
    sp = spm.SentencePieceProcessor()
    sp.Load(str(model_path))
    tokens = []
    for i in range(sp.GetPieceSize()):
        if sp.IsUnknown(i) or sp.IsControl(i):
            continue
        piece = sp.IdToPiece(i)
        if _BYTE_TOKEN_RE.match(piece):
            continue  # byte-fallback tokens are auto-generated; don't track them
        tokens.append(piece)
    return tokens


def get_new_tokens(model_path: str, base_token_set: Set[str]) -> List[str]:
    """Return tokens present in model that are not in base_token_set."""
    return [t for t in extract_tokens_from_model(model_path) if t not in base_token_set]


# ---------------------------------------------------------------------------
# Anchor tokens
# ---------------------------------------------------------------------------

def load_anchor_tokens(path: str) -> List[str]:
    """
    Load predefined anchor tokens from a text file.

    Format: one token per line; lines starting with '#' are comments.
    """
    with open(path, encoding='utf-8') as f:
        return [line.strip() for line in f if line.strip() and not line.startswith('#')]


# ---------------------------------------------------------------------------
# Deduplication
# ---------------------------------------------------------------------------

def deduplicate_partitions(
    partition_tokens: Dict[str, List[str]],
    strategy: str = 'coverage',
    min_coverage: int = 1,
) -> Dict[str, List[str]]:
    """
    Remove duplicate tokens across domain partition token lists.

    Args:
        partition_tokens:  {partition_name: [token, ...]} mapping of new tokens
                           learned by each domain trainer.
        strategy:          How to assign tokens that appear in multiple partitions.
            'first-wins'   Each token is kept only in the first partition that
                           listed it (iteration order of partition_tokens).
            'coverage'     Each token is kept only if it appears in at least
                           min_coverage partitions; assigned to the first.
                           Tokens below the threshold are dropped entirely.
        min_coverage:      Used with strategy='coverage'. A token that appears
                           in >= min_coverage partition lists is considered
                           cross-domain and worth keeping.

    Returns:
        A dict with the same keys, each containing a deduplicated token list.
        A token appears in exactly one partition's output list.
    """
    if strategy == 'first-wins':
        seen: Set[str] = set()
        result: Dict[str, List[str]] = {}
        for name, tokens in partition_tokens.items():
            unique = [t for t in tokens if t not in seen]
            seen.update(unique)
            result[name] = unique
        return result

    elif strategy == 'coverage':
        # Count how many distinct partitions each token appears in
        token_coverage: Counter = Counter()
        for tokens in partition_tokens.values():
            token_coverage.update(set(tokens))

        seen: Set[str] = set()
        result: Dict[str, List[str]] = {}
        for name, tokens in partition_tokens.items():
            unique = [
                t for t in tokens
                if t not in seen and token_coverage[t] >= min_coverage
            ]
            seen.update(unique)
            result[name] = unique
        return result

    else:
        raise ValueError(
            f"Unknown deduplication strategy: {strategy!r}. "
            "Valid options: 'first-wins', 'coverage'."
        )


# ---------------------------------------------------------------------------
# SentencePiece training helper
# ---------------------------------------------------------------------------

def train_spm(
    input_file: str,
    model_prefix: str,
    vocab_size: int,
    user_defined_symbols: List[str],
    character_coverage: float = 0.995,
    byte_fallback: bool = True,
) -> str:
    """
    Train a SentencePiece BPE model and return the path to the .model file.

    Args:
        input_file:            Path to the plain-text training corpus (one line per doc).
        model_prefix:          Output path prefix; SentencePiece appends .model and .vocab.
        vocab_size:            Total vocabulary size including special and user-defined tokens.
                               Must be > 4 (special tokens) + len(user_defined_symbols).
        user_defined_symbols:  Tokens guaranteed to appear in the vocabulary. SentencePiece
                               places these at the lowest IDs after the four special tokens,
                               giving them stable positions across successive training runs
                               that pass the same list.
        character_coverage:    Fraction of characters to cover (0.995 works well for English;
                               use 0.9995 for multilingual).
    """
    os.makedirs(os.path.dirname(model_prefix) or '.', exist_ok=True)

    spm.SentencePieceTrainer.train(
        input=input_file,
        model_prefix=model_prefix,
        vocab_size=vocab_size,
        model_type='bpe',
        character_coverage=character_coverage,
        split_digits=True,
        byte_fallback=byte_fallback,
        normalization_rule_name='nfkc',
        add_dummy_prefix=True,
        remove_extra_whitespaces=False,
        max_sentence_length=131768,
        user_defined_symbols=user_defined_symbols,
        minloglevel=1,
        pad_id=0, bos_id=1, eos_id=2, unk_id=3,
    )

    return f"{model_prefix}.model"


# ---------------------------------------------------------------------------
# Dataset text preparation
# ---------------------------------------------------------------------------

def prepare_training_text(datasets: Any, output_path: str, max_texts: int = 100000) -> str:
    """
    Write a HuggingFace dataset's text field to a plain-text file for SentencePiece.

    Args:
        datasets:     A HuggingFace Dataset or concatenated Dataset with a 'text' column.
        output_path:  Destination file path.
        max_texts:    Maximum number of lines to write (guards against enormous datasets).

    Returns:
        The output_path that was written.
    """
    os.makedirs(os.path.dirname(output_path) or '.', exist_ok=True)
    count = 0
    with open(output_path, 'w', encoding='utf-8') as f:
        for item in datasets:
            if count >= max_texts:
                break
            text = (item.get('text', '') if isinstance(item, dict) else str(item)).strip()
            if text:
                f.write(text + '\n')
                count += 1
    print(f"  Wrote {count:,} lines to {output_path}")
    return output_path


# ---------------------------------------------------------------------------
# HuggingFace wrapping
# ---------------------------------------------------------------------------

def wrap_as_hf_tokenizer(model_path: str, core_tokens: Dict[str, str], output_dir: str) -> Any:
    """
    Wrap a trained SentencePiece .model file as a HuggingFace T5Tokenizer
    and save it in a format that AutoTokenizer.from_pretrained() can load.

    Args:
        model_path:   Path to the .model file from SentencePiece training.
        core_tokens:  Dict with keys pad_token, bos_token, eos_token, unk_token.
        output_dir:   Directory to save the HuggingFace tokenizer files.

    Returns:
        The loaded tokenizer object.
    """
    from transformers import T5Tokenizer

    os.makedirs(output_dir, exist_ok=True)
    tokenizer = T5Tokenizer(vocab_file=model_path, extra_ids=0)
    tokenizer.pad_token = core_tokens['pad_token']
    tokenizer.bos_token = core_tokens['bos_token']
    tokenizer.eos_token = core_tokens['eos_token']
    tokenizer.unk_token = core_tokens['unk_token']
    tokenizer.save_pretrained(output_dir)
    return tokenizer
